package com.quantumweave.leadmanager.common; import com.quantumweave.leadmanager.lead.LeadNotFoundException; import org.springframework.http.HttpStatus; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(LeadNotFoundException.class) @ResponseStatus(HttpStatus.NOT_FOUND) Map<String,String> nf(LeadNotFoundException e){return Map.of("error",e.getMessage());}@ExceptionHandler(MethodArgumentNotValidException.class) @ResponseStatus(HttpStatus.BAD_REQUEST) Map<String,Object> val(MethodArgumentNotValidException e){Map<String,String> m=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->m.put(x.getField(),x.getDefaultMessage()));return Map.of("error","Validation failed","fields",m);}@ExceptionHandler(Exception.class) @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR) Map<String,String> all(Exception e){return Map.of("error","Unexpected server error");}}
